class FakeActions : IActionAdapter {
 public List<string> Calls=new List<string>();public bool Throw;public bool Running=true;
 void Add(string s){if(Throw)throw new IOException(new string('x',2000));lock(Calls)Calls.Add(s);}
 public bool Activate(string p){if(Running)Add("activate:"+p);return Running;}public void Launch(string p,string a,string d){Add("launch:"+p+"|"+a+"|"+d);}public void Open(string t){Add("open:"+t);}public void Key(string k){Add("key:"+k);}public void Mouse(string a,int n){Add("mouse:"+a+":"+n);}
}
class ActionBehaviorTests {
