 Check(!new WindowsActionAdapter().Activate(Path.Combine(Root,"missing-native-test.exe")),"native window search returns absent without launching nonexistent EXE");foreach(string token in new[]{"OpenTargetApplication","LaunchApplication"}){Reject(new ActionSpec{Action=token,ApplicationPath="Example.exe",Arguments="bad\0arg"},"NUL arguments refused "+token);Reject(new ActionSpec{Action=token,ApplicationPath="Example.exe",Arguments=new string('x',8193)},"oversized arguments refused "+token);Reject(new ActionSpec{Action=token,ApplicationPath="Example.exe",WorkingDirectory="\\\\server\\share"},"network working directory refused "+token);}
