 fake.Calls.Clear();var slow=new ActionSpec{Action="Sequence",Steps=new List<ActionSpec>{new ActionSpec{Action="Wait",WaitMilliseconds=10000},new ActionSpec{Action="Mouse"}}};Check(e.TryExecute(slow,Path.Combine(Root,"settings.json")),"bounded long sequence starts");Check(!e.TryExecute(sequence,Path.Combine(Root,"settings.json")),"overlap refused");e.Cancel();Check(e.WaitForIdle(1000)&&fake.Calls.Count==0,"cancellation interrupts wait and prevents later effects");Run(e,new ActionSpec{Action="Mouse",MouseAction="RightClick"});Check(fake.Calls.Count==1,"executor usable after cancellation");}
 fake.Calls.Clear();using(var e=new ActionExecutor(fake,null)){Check(e.TryExecute(new ActionSpec{Action="Sequence",Steps=new List<ActionSpec>{new ActionSpec{Action="Key",Key="Enter"},new ActionSpec{Action="Mouse"}}},Path.Combine(Root,"settings.json"),()=>fake.Calls.Count==0),"scoped sequence starts");Check(e.WaitForIdle(1000)&&fake.Calls.Count==1,"foreground guard rechecked before each effect");}fake.Calls.Clear();var exiting=new ActionExecutor(fake,null);exiting.TryExecute(new ActionSpec{Action="Sequence",Steps=new List<ActionSpec>{new ActionSpec{Action="Wait",WaitMilliseconds=10000},new ActionSpec{Action="Mouse"}}},Path.Combine(Root,"settings.json"));exiting.Dispose();Check(!exiting.Busy&&fake.Calls.Count==0&&!exiting.TryExecute(new ActionSpec{Action="Mouse"},Path.Combine(Root,"settings.json")),"dispose cancels sequence and refuses future execution");
 var logs=new List<string>();fake.Throw=true;using(var e=new ActionExecutor(fake,s=>logs.Add(s)))Run(e,new ActionSpec{Action="Mouse"});Check(logs.Count==1&&logs[0].Length<=512,"adapter error bounded and does not crash worker");fake.Throw=false;
 Reject(new ActionSpec{Action="Sequence",Steps=new List<ActionSpec>{new ActionSpec{Action="Sequence"}}},"nested sequence rejected");Reject(new ActionSpec{Action="Wait",WaitMilliseconds=1},"standalone wait rejected");Reject(new ActionSpec{Action="Mouse",MouseAction="Move"},"mouse movement forbidden");Reject(new ActionSpec{Action="Mouse",ScrollAmount=0},"zero wheel rejected");Reject(new ActionSpec{Action="Mouse",ScrollAmount=101},"wheel bound rejected");
 var tooMany=new ActionSpec{Action="Sequence",Steps=new List<ActionSpec>()};for(int i=0;i<33;i++)tooMany.Steps.Add(new ActionSpec{Action="Key"});Reject(tooMany,"33 steps rejected");tooMany.Steps.RemoveAt(32);ActionValidation.Validate(tooMany,false);Check(true,"32 steps accepted");var waits=new ActionSpec{Action="Sequence",Steps=new List<ActionSpec>()};for(int i=0;i<7;i++)waits.Steps.Add(new ActionSpec{Action="Wait",WaitMilliseconds=10000});Reject(waits,"cumulative 70 seconds rejected");waits.Steps.RemoveAt(6);ActionValidation.Validate(waits,false);Check(true,"cumulative 60 seconds accepted");waits.Steps[0].WaitMilliseconds=10001;Reject(waits,"single wait above 10 seconds rejected");
 foreach(string a in new[]{"LeftClick","RightClick","DoubleClick","Scroll"}){var packets=NativeActionInput.Mouse(a,-2);Check(packets.Length==(a=="DoubleClick"?4:a=="Scroll"?1:2),"native mouse packet count "+a);foreach(var p in packets)Check(p.Type==0&&p.Data.Mouse.X==0&&p.Data.Mouse.Y==0&&(p.Data.Mouse.Flags&0x8001)==0&&p.Data.Mouse.Extra.ToUInt64()==NativeActionInput.Sentinel,"mouse packet no move/absolute flags and own sentinel "+a);if(a=="Scroll")Check(unchecked((int)packets[0].Data.Mouse.Data)==-240,"signed wheel delta encoded");}
 var keys=NativeActionInput.Keys("Ctrl+Right");Check(keys.Length==4&&keys[1].Data.Key.Flags==1&&keys[2].Data.Key.Flags==3&&keys[3].Data.Key.Vk==17,"sequence key modifiers order and extended flags");Check(Marshal.SizeOf(typeof(NativeActionInput.Packet))==40,"native x64 input union size");
 string path=Path.Combine(Root,"settings.json");var cfg=RemoteConfig.Parse("{\"MurglarPath\":\"Example.exe\"}");cfg.Buttons.Add("1",new ButtonConfig{Scope="Global",InputType="Keyboard",Usage=113,ScanCode=60,ScanFlags=2});cfg.Save(path);
 var details=new List<ActionSpec>{new ActionSpec{Action="LaunchApplication",ApplicationPath="Example.exe",Arguments="--a \"b c\"",WorkingDirectory="."},new ActionSpec{Action="OpenTarget",Target="https://example.com/"},new ActionSpec{Action="Mouse",MouseAction="Scroll",ScrollAmount=-4},sequence};
 foreach(var a in details){using(var f=new SettingsForm(path)){f.SelectButton("1");f.SetEditor(a.Action,"Ctrl+Right","Global",false,650,200);f.SetActionDetails(a);Check(f.SaveCurrent(),"actual GUI Save "+a.Action);}var b=RemoteConfig.Load(path).Buttons["1"];Check(b.InputType=="Keyboard"&&b.Usage==113&&b.ScanCode==60&&b.ScanFlags==2&&b.Delay==650&&b.Interval==200&&!b.Repeat,"GUI action preserves learned identity and timing "+a.Action);using(var f=new SettingsForm(path)){f.SelectButton("1");var r=f.EditorActionDetails;Check(r.Action==a.Action&&r.ApplicationPath==a.ApplicationPath&&r.Arguments==a.Arguments&&r.WorkingDirectory==a.WorkingDirectory&&r.Target==a.Target&&r.MouseAction==a.MouseAction&&r.ScrollAmount==a.ScrollAmount&&(a.Action!="Sequence"||r.Steps.Count==6),"all GUI parameters reopen "+a.Action);}}
