 static void RuntimeTest(string path){var t=typeof(RemoteConfig).Assembly.GetType("RockTekRemote");var flags=BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance|BindingFlags.Static;var runtime=FormatterServices.GetUninitializedObject(t);Action<string,object> set=(n,v)=>t.GetField(n,flags).SetValue(runtime,v);Func<string,object> get=n=>t.GetField(n,flags).GetValue(runtime);set("Clock",Stopwatch.StartNew());set("Repeater",new HoldRepeater());set("LogFile",Path.Combine(Root,"runtime.log"));set("ConfigPath",path);set("ConfigUsesLocator",false);var fake=new FakeActions();set("ActionAdapter",fake);var c=RemoteConfig.Load(path);var b=c.Buttons["1"];b.Action="Mouse";b.Steps=null;b.Repeat=false;b.Scope="Global";c.Save(path);t.GetMethod("Reload",flags).Invoke(runtime,null);var input=new RemoteInputEvent{InputType="Keyboard",Code=113};t.GetMethod("HandleInput",flags).Invoke(runtime,new object[]{"AABBCCDDEEFF",input,false});var e=(ActionExecutor)get("Executor");Check(e.WaitForIdle(1000)&&fake.Calls.Count==1,"actual runtime boundary dispatches selected mouse through fake adapter");t.GetMethod("HandleInput",flags).Invoke(runtime,new object[]{"AABBCCDDEEFF",input,false});Check(fake.Calls.Count==1,"held duplicate no click storm");t.GetMethod("ClearHeld",flags).Invoke(runtime,new object[]{0L});b.Scope="Application";b.ScopeApplicationPath="Example.exe";c.Save(path);t.GetMethod("Reload",flags).Invoke(runtime,null);t.GetMethod("HandleInput",flags).Invoke(runtime,new object[]{"AABBCCDDEEFF",input,false});Check(fake.Calls.Count==1,"target scope rejects when no configured active app");b.Scope="Global";b.Action="Sequence";b.Steps=new List<ActionSpec>{new ActionSpec{Action="Wait",WaitMilliseconds=10000},new ActionSpec{Action="Mouse"}};c.Save(path);t.GetMethod("Reload",flags).Invoke(runtime,null);t.GetMethod("HandleInput",flags).Invoke(runtime,new object[]{"AABBCCDDEEFF",input,false});c.Buttons["Left"].Key="Enter";c.Save(path);t.GetMethod("Reload",flags).Invoke(runtime,null);Check(e.WaitForIdle(1000)&&fake.Calls.Count==1,"runtime config reload cancels pending sequence");t.GetMethod("ClearHeld",flags).Invoke(runtime,new object[]{0L});t.GetMethod("HandleInput",flags).Invoke(runtime,new object[]{"AABBCCDDEEFF",input,false});set("HomeLock",new object());set("PendingHomes",new List<long>());set("HookLogs",new System.Collections.Concurrent.ConcurrentQueue<string>());using(var lease=new LearnGate()){t.GetMethod("Tick",flags).Invoke(runtime,null);Check(e.WaitForIdle(1000)&&fake.Calls.Count==1,"learning lease cancels an in-flight sequence without effects");}foreach(string kind in new[]{"LaunchApplication","OpenTarget","Sequence","Key"}){t.GetMethod("ClearHeld",flags).Invoke(runtime,new object[]{0L});b.Action=kind;b.Steps=kind=="Sequence"?new List<ActionSpec>{new ActionSpec{Action="Key",Key="Enter"}}:null;b.ApplicationPath="Example.exe";b.Arguments="--exact \"a b\"";b.WorkingDirectory=".";b.Target="https://example.com/";b.Key="Ctrl+Right";c.Save(path);t.GetMethod("Reload",flags).Invoke(runtime,null);int before=fake.Calls.Count;t.GetMethod("HandleInput",flags).Invoke(runtime,new object[]{"AABBCCDDEEFF",input,false});Check(e.WaitForIdle(1000)&&fake.Calls.Count==before+1,"actual runtime dispatch "+kind+" uses isolated fake adapter");}c.TargetApplicationPath="Example.exe";c.Save(path);t.GetMethod("Reload",flags).Invoke(runtime,null);int homeBefore=fake.Calls.Count;t.GetMethod("HandleUsage",flags).Invoke(runtime,new object[]{"AABBCCDDEEFF",(ushort)0x223,false});Check(e.WaitForIdle(1000)&&fake.Calls.Count==homeBefore+1&&fake.Calls[fake.Calls.Count-1]=="activate:"+Path.Combine(Root,"Example.exe"),"default Home dispatch targets selected EXE through worker, not browser");e.Dispose();GC.SuppressFinalize(runtime);}
